import { readdir, writeFile } from "node:fs/promises";
const DIR = "public/assets/photos";
const files = await readdir(DIR);
const map = {};
for (const f of files) {
  const m = f.match(/^(.+)-(\d+)\.(avif|webp)$/);
  if (!m) continue;
  const [, stem, width] = m;
  (map[stem] ??= new Set()).add(Number(width));
}
const out = Object.fromEntries(
  Object.entries(map).map(([k, v]) => [k, [...v].sort((a, b) => a - b)]),
);
await writeFile(
  "app/(marketing)/_sections/photo-widths.ts",
  `/**
 * Generated by convert-images.mjs — do not edit by hand.
 *
 * Which rendered widths actually exist for each photograph. Sources are never
 * upscaled, so a 900px original has no 1600px variant; advertising one in a
 * srcset would make the browser request a file that is not there.
 */
export const photoWidths: Record<string, number[]> = ${JSON.stringify(out, null, 2)};
`,
);
console.log("slots:", Object.keys(out).length);
console.log("width spread:", JSON.stringify(
  Object.values(out).reduce((a, w) => { a[w.join("/")] = (a[w.join("/")] ?? 0) + 1; return a; }, {})
));
